    def link(self, path, label=None):
        p = self.root / path
        if not p.exists():
            return esc(label or path)+" (pending)"
        href = quote(os.path.relpath(p, self.output.parent), safe="/._-")
        return '<a href="'+href+'">'+esc(label or path)+'</a>'

    def image(self, path, caption):
        if not (self.root / path).exists():
            return '<p>'+esc(caption)+': figure pending.</p>'
        href = quote(os.path.relpath(self.root / path, self.output.parent), safe="/._-")
        return f'<figure><img loading="lazy" src="{href}" alt="{esc(caption)}"><figcaption>{esc(caption)}</figcaption></figure>'


def table(headers, data):
    if not data:
        return '<p>Selected-case results are pending.</p>'
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in row)+'</tr>' for row in data)+'</tbody></table></div>'


def details(label, value):
    def clean(x):
        if isinstance(x, float) and not math.isfinite(x):
            return "nonfinite; unavailable"
        if isinstance(x, dict):
            return {k: clean(v) for k, v in x.items()}
        if isinstance(x, list):
            return [clean(v) for v in x]
        return x
    return '<details><summary>'+esc(label)+'</summary><pre>'+esc(json.dumps(clean(value), indent=2, allow_nan=False))+'</pre></details>'


def ct_case(root, name):
    if not isinstance(name, str) or not re.fullmatch(r"[A-Za-z0-9_.-]+", name):
        return False
    folder = root / "results" / name
    try:
        meta = json.loads((folder / "metadata.json").read_text())
        scheme = meta.get("scheme", "").lower()
        return completed_output(folder) and "athena" in scheme and ("constrained transport" in scheme or "staggered ct" in scheme)
    except (OSError, ValueError, TypeError):
        return False


def selected_context(records):
    selection = records.load("results/reference_selection.json", True)
    name = selection.get("reference_case")
    if not ct_case(records.root, name):
        raise Refusal("An explicitly selected, completed native Athena CT case is required; no CT final report was written.")
    folder = records.root / "results" / name
    config = cfg(folder / "run.cfg")
    stats = records.load(f"results/{name}/statistics.json", True)
