    meta = records.load(f"results/{name}/metadata.json", True)
    summary = records.load("results/summary.json", True)
    if summary.get("reference_case") != name:
        raise Refusal("Postprocessing summary does not match the explicit CT selection; regenerate postprocess.py first.")
    convention = selection.get("time_convention", "simultaneous_geometric_UTC")
    if convention not in ("observer_arrival", "simultaneous_geometric_UTC") or summary.get("time_convention", "simultaneous_geometric_UTC") != convention:
        raise Refusal("Selection/summary comparison-clock mismatch.")
    if summary.get("reference_selection", {}) != selection:
        raise Refusal("Summary records a different selection/control set; regenerate postprocessing.")
    selected = summary.get("cases", {}).get(name, {})
    trace = rows(folder / "ct_trace.csv")
    stage = rows(folder / "stage_trace.csv")
    if not trace or int(stats.get("steps", 0)) <= 0 or len(stage) != stats.get("stage_calls") or len(stage) != 2*stats["steps"]:
        raise Refusal("Native accepted-step/stage completion records are incomplete.")
    if abs(float(trace[0]["day"])-float(config["start_day"])) > 1e-10 or abs(float(trace[-1]["day"])-float(config["end_day"])) > 1e-10:
        raise Refusal("Native trace did not reach the requested CT endpoints.")
    if len(trace) != stats["steps"]+1 or any(float(b["day"]) <= float(a["day"]) for a, b in zip(trace, trace[1:])):
        raise Refusal("Native accepted-step trace length/order is inconsistent.")
    for index, row in enumerate(stage):
        expected_stage = index%2+1
        if int(float(row["stage"])) != expected_stage or abs(float(row["base_day"])-float(trace[index//2]["day"])) > 1e-12 or abs(float(row["rhs_day"])-float(row["base_day"])-(expected_stage-1)*float(row["full_dt"])) > 1e-12:
            raise Refusal("Actual native RK stage epochs disagree with accepted-step times.")
    comet = [float(row["day"]) for row in rows(folder / "probe.csv") if int(float(row["probe_id"])) == 0]
    window = summary.get("published_window_day", [])
    if len(window) != 2 or not comet or min(comet) > window[0]-(1100/86400 if convention == "observer_arrival" else 0) or max(comet) < window[1]:
        raise Refusal("Selected comet probe does not cover the complete published pointing and required light-time margin.")
    if status.get("execution_complete") is False:
        raise Refusal("Controller explicitly records incomplete execution.")
    mean = selected.get("PN_GTI_weighted_mean", {})
    if not all(finite(mean.get(k)) and mean[k] > 0 for k in KEYS):
        raise Refusal("Finite positive selected-case PN density, speeds and both flux definitions are required.")
    for p in (folder / "run.cfg", folder / "ct_trace.csv", folder / "stage_trace.csv", folder / "probe.csv"):
        records.read[str(p.relative_to(records.root))] = sha(p)
    return dict(name=name, folder=folder, cfg=config, stats=stats, status=status, meta=meta, summary=summary, selected=selected, selection=selection, convention=convention, trace=trace)


def physics_identity(config):
    defaults = {"gamma": "1.5", "thermal_pressure_factor": "2", "boundary_speed_thermo_closure": "0", "boundary_n_v2_cm3_kms2": "0", "boundary_T_over_v2_K_per_kms2": "0", "density_scale": "1", "temperature_scale": "1", "magnetic_scale": "1", "boundary_speed_offset_kms": "0", "map_rotation_rad_day": "0", "map_epoch_day": "0", "map_longitude_offset_rad": "0", "source_surface_au": "0", "ct_mode": "real", "boundary_map_csv": "", "cme_boundary_csv": ""}
    result = {}
    for key, default in defaults.items():
        value = config.get(key, default)
        try:
            result[key] = float(value)
        except ValueError:
            result[key] = value
    return result


def selected_checks(context, root, plan=None):
    result, data = {}, []
    for category in ("spatial", "temporal", "domain", "physics"):
        expected = [tuple(pair) for pair in context["selection"].get(category+"_comparisons", [])]
        recorded = {(c.get("left"), c.get("right")): c for c in context["summary"].get("selected_reference_checks", {}).get(category, [])}
        checked = []
        for pair in expected:
            check = recorded.get(pair, {})
            valid = bool(check) and all(ct_case(root, name) for name in pair)
            if valid and category in ("spatial", "temporal"):
                valid = physics_identity(cfg(root / "results" / pair[0] / "run.cfg")) == physics_identity(cfg(root / "results" / pair[1] / "run.cfg"))
            differences = {k: check.get("comparison", {}).get(k, {}).get("maximum_relative_difference") for k in ("n", "v", "f_incident")}
            valid = valid and all(finite(v) and v >= 0 for v in differences.values())
            targets = check.get("targets")
            passed = None
            if targets:
                registered = ((plan or {}).get("conditional_coordinate_refinement", {}).get("maximum_pointwise_relative_targets") if category == "spatial" else {k: (plan or {}).get("temporal_control", {}).get("maximum_pointwise_n_v_incident_flux_relative_change") for k in differences} if category == "temporal" else None)
                if category in ("spatial", "temporal") and (not registered or registered != targets):
                    valid = False
                passed = valid and all(finite(targets.get(k)) and differences[k] <= targets[k] for k in differences)
                if check.get("passed") is not passed:
                    valid = False;passed = False
            label = "pass" if passed is True else "fail" if passed is False else "sensitivity only" if valid else "missing/invalid"
            data.append([category, " / ".join(pair), *(pct(differences[k]) for k in differences), label])
            checked.append(dict(left=pair[0], right=pair[1], valid=valid, maximum_relative_differences=differences, targets=targets, passed=passed))
        result[category] = {"comparisons": checked, "all_registered_targets_passed": bool(checked) and all(x["valid"] and x["passed"] is True for x in checked) if category in ("spatial", "temporal") else None}
    return result, data


