#!/usr/bin/env python3
"""Check that completed runs still have their recorded physics and input files."""
from pathlib import Path
from datetime import datetime, timezone
import hashlib,json
from run_records import completed_output

ROOT=Path(__file__).resolve().parents[1]

def main():
    hashes={};results={};problems=[];without_receipts=[]
    def digest(path):
        name=str(path)
        if name not in hashes:hashes[name]=hashlib.sha256(path.read_bytes()).hexdigest() if path.exists() else None
        return hashes[name]
    for directory in sorted((ROOT/'results').iterdir()):
        receipt=directory/'input_code_provenance.json'
        if not completed_output(directory):continue
        if not receipt.exists():without_receipts.append(directory.name);continue
        recorded=json.loads(receipt.read_text());checks=[];archived=[]
        archive_receipt=directory/'provenance_archives.json'
        archives=json.loads(archive_receipt.read_text()).get('files',{}) if archive_receipt.exists() else {}
        for name,expected in recorded.items():
            actual=digest(ROOT/name)
            if actual!=expected and name in archives:
                archive=archives[name]['archive'];archived_actual=digest(ROOT/archive)
                if archived_actual==expected:
                    archived.append({'original_path':name,'verified_archive':archive});actual=archived_actual
            checks.append(actual==expected)
            if actual!=expected:problems.append({'case':directory.name,'file':name,'recorded':expected,'actual':actual})
        results[directory.name]={'files_checked':len(checks),'all_match':all(checks),'matched_archives':archived}
    report={'created_utc':datetime.now(timezone.utc).isoformat(),'scope':'Completed results/ runs with a stored input_code_provenance.json. Tests and third-party acquisitions have separate receipts.',
        'runs':results,'unique_files_hashed':len(hashes),'problems':problems,'passed':not problems,
        'legacy_runs_without_runtime_hash_receipts':without_receipts,'receipt_coverage_complete':not without_receipts,
        'coverage_limit':'Early runs predate the runtime hash recorder. Their saved configurations/results remain historical evidence; matching current files cannot retrospectively certify their original runtime hashes.'}
    (ROOT/'validation/run_provenance_audit.json').write_text(json.dumps(report,indent=2)+'\n')
    print(json.dumps({'runs_checked':len(results),'unique_files_hashed':len(hashes),'problems':problems,'passed':not problems},indent=2))
    if problems:raise SystemExit(1)

if __name__=='__main__':main()
